dest = start_row
counts = {}
for sheet in source_order:
    val_ws = vals[sheet]
    cols = selected_columns(sheet)
    # Ensure we have up to 11 columns; if fewer, pad; if more, truncate.
    if len(cols) < 11:
        cols = cols + [None] * (11 - len(cols))
    else:
        cols = cols[:11]
    n = 0
    max_r = val_ws.max_row
    for r in range(2, max_r + 1):
        values = []
        any_val = False
        for c in cols:
            if c is None:
                v = None
            else:
                v = val_ws.cell(row=r, column=c).value
            v = clean_value(v)
            if v is not None:
                any_val = True
            values.append(v)
